function activeTarget(){return ensureCombatTargetSelection(true)}
function stunAttempt(t){state.guardian.stamina-=14;strike(t,.72,2,-2);if(t.hp>0){const odds=clamp(28+boundedStatValue(stat(state,'str'))*1.65+boundedClassRank(classRank())*.9-(t.boss?18:0),15,78);if(rnd(1,100)<=odds){t.stunned=1;createCombatOpening(t,'staggered',state.name,1);combat.log.push(SOSText("combat_combat.stunAttempt.001",t.name))}else combat.log.push(SOSText("combat_combat.stunAttempt.002",t.name))}}
function exploitOpening(t,kind){if(!combat.opening||combat.opening.target!==t.id){combat.log.push(SOSText("combat_combat.exploitOpening.001"));return}const focus=spendGuardianFocus(kind==='rogue'?16:12),focusMult=1+focus*.012,focusAcc=Math.floor(focus*.45),focusCrit=Math.floor(focus*.35);if(kind==='rogue')strike(t,1.62*focusMult,16+focusAcc,18+focusCrit,{precise:true});else strike(t,1.30*focusMult,20+focusAcc,12+focusCrit,{precise:true});if(focus)combat.log.push(`${kind==='rogue'?'Exploit Opening':'Called Shot'} converts ${focus} Focus into a stronger precision attack.`);combat.log.push(kind==='rogue'?'Exploit Opening punishes the exposed target.':SOSText("combat_combat.exploitOpening.002"));clearCombatOpening(t)}
function sorcererAttack(t,over=false){const s=combat.surge||0,power=1+Math.min(35,s)*.004+(s>35?Math.min(45,s-35)*.007:0)+(s>80?Math.min(20,s-80)*.004:0);strike(t,(over?1.52:1.02)*power,over?-2:7,over?9:2,{precise:true});combat.surge=clamp(s+(over?30:12),0,100);if(over)state.guardian.stamina-=18;const risk=Math.max(0,(combat.surge-62)/95);if(combat.surge>=70&&chance(risk)){const back=rnd(5,12)+Math.floor((combat.surge-70)/10);state.guardian.hp-=back;combat.log.push(SOSText("combat_combat.sorcererAttack.001",back))}}
function combatControlWatchdog(c){
 setTimeout(()=>{
   if(combat!==c||c.enemyPhase)return;
   const activeModal=document.querySelector('.overlay');
   if(!activeModal){repairCombatTurnState(SOSText("combat_combat.combatControlWatchdog.001"));return renderCombat()}
   const grid=activeModal.querySelector('.combat-grid');
   if(grid&&!grid.querySelector('[data-act]')){repairCombatTurnState(SOSText("combat_combat.combatControlWatchdog.002"));renderCombat()}
 },40)
}
function safePlayerAction(act){
 if(!combat)return renderGame();repairCombatTurnState('input');const c=combat;if(!c)return renderGame();if(c.actionBusy){if(Date.now()-(c.actionBusyAt||0)<=350)return;c.actionBusy=false}c.actionBusy=true;c.actionBusyAt=Date.now();
 try{return playerAction(act)}catch(err){console.error(SOSText("combat_combat.safePlayerAction.001"),err);reportCombatJavascriptError(err,SOSText("combat_combat.safePlayerAction.002",act));if(!combat)return renderGame();combat.enemyPhase=null;combat.guardianSkip=false;combat.over=false;combat.log.push(SOSText("combat_combat.safePlayerAction.003"));return renderCombat()}finally{if(combat===c){c.actionBusy=false;c.actionBusyAt=0;combatControlWatchdog(c)}}
}
function playerAction(act){if(!combat)return;if(combat.over){repairCombatTurnState('action');if(combat.over)return}const g=state.guardian;if(g.hp<=0){if(act==='retreat')return attemptRetreat();if(act!=='company')return;allyTurn();if(combat.enemies.every(e=>e.hp<=0))return finishCombat(true);return enemyTurn()}if(combat.guardianSkip){if(act==='retreat')return attemptRetreat();if(act!=='skip')return;combat.guardianSkip=false;combat.log.push(SOSText("combat_combat.playerAction.001"));allyTurn();if(combat.enemies.every(e=>e.hp<=0))return finishCombat(true);return enemyTurn()}const t=activeTarget();if(!t)return finishCombat(true);let endedTurn=true;if(act==='attack'){strike(t,1,0,0);if(guardianClass()==='Berserker')combat.fury=clamp((combat.fury||0)+8,0,100);if(['Ranger','Rogue'].includes(guardianClass()))gainGuardianFocus(3)}else if(act==='power'){g.stamina-=18;strike(t,1.58+boundedClassRank(classRank())*.018,-14+Math.min(6,Math.floor(boundedClassRank(classRank())/3)),5);if(t.hp>0&&!combat.opening&&chance(.32))createCombatOpening(t,'guardBroken',state.name,2)}else if(act==='stun')stunAttempt(t);else if(act==='rage'){const spent=berserkerFurySpend();combat.fury=Math.max(0,(combat.fury||0)-spent);strike(t,1.45+spent*.012,-4,8+Math.floor(spent*.12));combat.log.push(`Fury Smash spends ${spent} Fury.`)}else if(act==='exploit')exploitOpening(t,'rogue');else if(act==='called')exploitOpening(t,'ranger');else if(act==='surgebolt')sorcererAttack(t,false);else if(act==='overchannel')sorcererAttack(t,true);else if(act==='rapid'){g.stamina-=16;const br=boundedClassRank(classRank()),focus=guardianFocus();strike(t,.66+br*.008,3+Math.floor(br/4)+Math.floor(focus/12),-2);if(t.hp>0)strike(t,.66+br*.008,Math.floor(br/5)+Math.floor(focus/16),-2);gainGuardianFocus(4,'Rapid Strike builds pressure.');if(t.hp>0&&!combat.opening&&chance(.26+Math.min(.14,guardianFocus()/200)))createCombatOpening(t,'pinned',state.name,2)}else if(act==='bolt')wizardAttack(t,false);else if(act==='blast'){g.stamina-=20;wizardAttack(t,true)}else if(act==='spell'){endedTurn=false;return showSpellSelect()}else if(act==='brace'){g.stamina-=8;combat.guardianBrace=true;combat.log.push(SOSText("combat_combat.playerAction.003"))}else if(act==='guard'){g.stamina-=10;endedTurn=false;return showGuardTargets()}else if(act==='command'){g.stamina-=10;endedTurn=false;return showCommandOrders()}else if(act==='reposition'){g.stamina-=8;combat.reposition=true;gainGuardianFocus(guardianClass()==='Rogue'?14:12);combat.log.push(SOSText("combat_combat.playerAction.004"))}else if(act==='vent'){ventSorcererSurge()}else if(act==='item'){endedTurn=false;showCombatItems();return}else if(act==='retreat'){attemptRetreat();return}if(combat.enemies.every(e=>e.hp<=0))return finishCombat(true);if(endedTurn){allyTurn();if(combat.enemies.every(e=>e.hp<=0))return finishCombat(true);enemyTurn()}}
function showSpellSelect(){modalRouteEnter(SOSText("combat_combat.showSpellSelect.001"),Array.from(arguments));const cur=state.guardian.element||'none';overlay(SOSText("combat_combat.showSpellSelect.002",[['none','Unattuned','Reliable neutral magic.'],['fire','Fire','Highest damage; may Burn.'],['water','Water','Slows and weakens enemy accuracy.'],['earth','Earth','Breaks armor and may Stagger.'],['air','Air','Accurate disruption that delays initiative.']].map(([id,n,d])=>`<button data-element="${id}" ${cur===id?'disabled':''}><b>${n}</b><br><small>${d}</small></button>`).join('')),true);document.querySelectorAll('[data-element]').forEach(b=>b.onclick=()=>{state.guardian.element=b.dataset.element;combat.log.push(SOSText("combat_combat.showSpellSelect.003",b.dataset.element==='none'?'neutral force':b.dataset.element));sfxCombatAttack('magic',false,false,false);save();closeOverlay();renderCombat()});$('#spellBack').onclick=renderCombat}
function wizardAttack(t,blast=false){const el=state.guardian.element||'none',rank=boundedClassRank(classRank()),mind=boundedStatValue(stat(state,'int')),base=10+mind*.9+rank*.72+(blast?9+rank*.28:0),score=72+mind*.9+rank*.35+(blast?-8:6)+guardianClassBonus().accuracy,hit=combatHitChance(score,enemyEvasion(t),35,94);if(rnd(1,100)>hit){combat.log.push(SOSText("combat_combat.wizardAttack.001",blast?'Magical Blast':'Magical Bolt',t.name));sfxCombatAttack('magic',false,false,blast);return}let dmg=Math.round(base+rnd(0,5));if(el==='fire')dmg=Math.round(dmg*1.18);if(el==='earth'&&['armored','stone','shield'].includes(t.trait))dmg=Math.round(dmg*1.3);t.hp-=dmg;combat.log.push(SOSText("combat_combat.wizardAttack.002",el==='none'?'Arcane':el[0].toUpperCase()+el.slice(1),blast?'Blast':'Bolt',t.name,dmg));sfxCombatAttack('magic',true,['armored','stone','shield'].includes(t.trait),blast);if(el==='fire'&&chance(blast?.55:.3)){t.burning=Math.max(t.burning||0,blast?3:2);combat.log.push(SOSText("combat_combat.wizardAttack.003",t.name))}if(el==='water'&&chance(blast?.7:.45)){t.waterSlow=Math.max(t.waterSlow||0,2);combat.log.push(SOSText("combat_combat.wizardAttack.004",t.name))}if(el==='earth'&&chance(blast?.6:.35)){t.armorBroken=Math.max(t.armorBroken||0,2);if(blast&&chance(.35))t.staggered=true;combat.log.push(SOSText("combat_combat.wizardAttack.005",t.name))}if(el==='air'){t.airDisrupt=Math.max(t.airDisrupt||0,2);if(blast&&chance(.45))t.staggered=true;combat.log.push(SOSText("combat_combat.wizardAttack.006",t.name))}if(blast&&el==='fire'){const other=combat.enemies.find(e=>e.hp>0&&e!==t);if(other&&chance(.35)){const splash=Math.max(4,Math.round(dmg*.35));other.hp-=splash;combat.log.push(SOSText("combat_combat.wizardAttack.007",other.name,splash))}}}
function showGuardTargets(){modalRouteEnter(SOSText("combat_combat.showGuardTargets.001"),Array.from(arguments));const targets=[['guardian',state.name],...partyMembers(true).filter(m=>m.hp>0).map(m=>[m.id,m.name])];overlay(SOSText("combat_combat.showGuardTargets.002",targets.map(([id,n])=>`<button data-guardtarget="${id}">${esc(n)}</button>`).join('')));document.querySelectorAll('[data-guardtarget]').forEach(b=>b.onclick=()=>{combat.wardenGuard=b.dataset.guardtarget;combat.log.push(SOSText("combat_combat.showGuardTargets.003",b.dataset.guardtarget==='guardian'?state.name:ownerName(b.dataset.guardtarget)));allyTurn();enemyTurn()});$('#guardBack').onclick=renderCombat}
function showCommandOrders(){modalRouteEnter(SOSText("combat_combat.showCommandOrders.001"),Array.from(arguments));overlay(SOSText("combat_combat.showCommandOrders.002"));document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{combat.commandOrder=b.dataset.order;combat.log.push(SOSText("combat_combat.showCommandOrders.003",b.dataset.order==='focus'?'focus fire':b.dataset.order==='press'?'press the attack':'hold formation'));allyTurn();enemyTurn()});$('#commandBack').onclick=renderCombat}
function guardedEnemyTarget(t,precise=false,attacker=SOSText("combat_combat.guardedEnemyTarget.001")){if(!t||t.hp<=0||precise||t.trait==='shield')return t;const guard=combat.enemies.find(e=>e.hp>0&&e.trait==='shield'&&!(e.guardBroken>0));const protectPriority=['commander','healer','mage'].includes(t.trait);if(guard&&chance(protectPriority?.78:.55)){combat.log.push(SOSText("combat_combat.guardedEnemyTarget.002",guard.name,attacker==='You'?'your attack':attacker+"'s attack",t.name));return guard}return t}
