// Evasion and armor protection are deliberately separate so mobile and armored builds defend differently.
function combatHitChance(score,evasion=0,min=25,max=94){const x=(Number(score)||0)-(Number(evasion)||0),p=65+28*Math.tanh((x-55)/45);return clamp(Math.round(p),min,max)}
function enemyEvasion(e){if(!e)return 0;const trait={fast:6,assassin:8,duelist:7,skirmisher:4,archer:3,marauder:2,charger:2,mage:2}[e.trait]||0,statePenalty=(e.staggered?6:0)+(e.exposed>0?5:0)+(e.pinned>0?5:0)+(e.distracted>0?3:0)+(e.offBalance>0?4:0)+(e.marked>0?2:0);return Math.max(0,Math.round(Math.max(0,(e.init||5)-5)*.55+trait-statePenalty))}
function armorEvasionAdjustment(it){const w=armorWeight(it);if(w===SOSText("core_state_party_classes.armorWeight.001"))return-4;if(w===SOSText("core_state_party_classes.armorWeight.002"))return-1;if(w===SOSText("core_state_party_classes.armorWeight.003"))return 3;return 0}
function guardianEvasion(){const dex=boundedStatValue(stat(state,'dex'))*.28,armor=armorEvasionAdjustment(item(state.guardian.equipment.armor)),training=Math.min(4,(guardianClassBonus().initiative||0)*.3),mobile=(combat?.reposition?8:0)+(combat?.swift?4:0);return Math.max(0,Math.round(dex+armor+training+mobile))}
function allyEvasion(m){const dex=boundedStatValue(allyStat(m,'dex'))*.25,armor=armorEvasionAdjustment(item(m.equipment?.armor)),training=Math.min(3,(allyClassBonus(m).initiative||0)*.25);return Math.max(0,Math.round(dex+armor+training))}
function guardianCritChance(critMod=0,w=weapon()){return clamp(Math.round(4+boundedStatValue(stat(state,'dex'))*.34+critMod+(w.id==='named_blade'?8:0)),3,36)}
function strike(t,mult,accMod,critMod,opts={}){t=guardedEnemyTarget(t,!!opts.precise);const w=weapon(),hit=combatHitChance(accuracy()+accMod,enemyEvasion(t),20,94),heavy=mult>=1.45;if(rnd(1,100)>hit){combat.log.push(SOSText("combat_combat.strike.001",t.name));sfxAttackForGuardian(false,t,heavy);return}let dmg=Math.max(1,Math.round((w.damage+damageBonus()+rnd(0,6))*mult));const critChance=guardianCritChance(critMod,w);if(rnd(1,100)<=critChance){dmg=Math.round(dmg*1.6);combat.log.push(SOSText("combat_combat.strike.002"))}if(t.trait==='armored'||t.trait==='stone'||t.trait==='shield'){const reduction=(t.armorBroken||t.guardBroken>0)?.94:.82;dmg=Math.round(dmg*(weaponFamily(w)===SOSText("combat_combat.strike.003")?1.08:w.id==='named_hammer'?1.15:reduction))}if(t.exposed>0||t.offBalance>0)dmg=Math.round(dmg*1.10);if(t.marked>0&&combatFamily()==='ranged')dmg=Math.round(dmg*1.08);if(w.id==='named_sword')dmg+=Math.floor(state.town.morale/20);t.hp-=dmg;combat.log.push(SOSText("combat_combat.strike.004",t.name,dmg));sfxAttackForGuardian(true,t,heavy)}
function companionTargetScore(m,e){if(!e||e.hp<=0)return-999;const cls=m.className||allyDef(m.id)?.className,selected=combatSelectedTarget(),coord=companionCoordinationScore(m);let score=10+(1-e.hp/e.maxHp)*7;if(selected?.id===e.id)score+=6+coord*.06;if(['healer','commander','mage'].includes(e.trait))score+=cls==='Ranger'||cls==='Rogue'?16:10;if(e.trait==='assassin')score+=10;if((m.role==='archer'||m.role==='scout')&&['healer','commander','mage','archer','engineer'].includes(e.trait))score+=13;if(m.role==='defector'&&['commander','elite','mage'].includes(e.trait))score+=14;if(m.role==='spear'&&['armored','stone','brute','shield'].includes(e.trait))score+=14;if(m.role==='spawn'&&['commander','brute','engineer'].includes(e.trait))score+=12;if(guardianOpeningClass()&&!combat.opening)score+=Math.max(0,companionSetupPriority(m,e)-10)*.65;if(combat.opening?.target===e.id&&companionPreservesOpeningForGuardian(m))score-=14;return score+rnd(0,4)}
function allyTarget(m){const alive=combat.enemies.filter(e=>e.hp>0);if(!alive.length)return null;return alive.slice().sort((a,b)=>companionTargetScore(m,b)-companionTargetScore(m,a))[0]||activeTarget()||alive[0]}
function allyHeal(m){const coord=companionCoordinationScore(m),candidates=[{kind:'guardian',name:state.name,hp:state.guardian.hp,max:maxHP()},...partyMembers(true).filter(x=>x.id!==m.id).map(x=>({kind:'ally',member:x,name:x.name,hp:x.hp,max:allyMaxHP(x)}))].filter(x=>x.hp<x.max).sort((a,b)=>(a.hp<=0?0:1)-(b.hp<=0?0:1)||a.hp/a.max-b.hp/b.max);if(!candidates.length)return false;const target=candidates[0],threshold=.56+coord*.0018;if(target.hp>0&&target.hp>=target.max*clamp(threshold,.58,.74))return false;const wasDown=target.hp<=0,amount=10+Math.floor(allyStat(m,'wis')*.7)+rnd(0,5)+allyClassBonus(m).healing+companionBonuses(m).healing;if(target.kind==='guardian')state.guardian.hp=Math.min(target.max,Math.max(0,state.guardian.hp)+amount);else target.member.hp=Math.min(target.max,Math.max(0,target.member.hp)+amount);combat.log.push(SOSText("combat_combat.allyHeal.001",m.name,wasDown?'revives':'tends',target.name,amount));if(coord>=70&&target.hp/target.max<.42)combat.log.push(`${m.name} recognizes the danger and prioritizes keeping ${target.name} in the fight.`);return true}
function allyStrike(m,t,mult=1,accMod=0,label='hits'){t=guardedEnemyTarget(t,false,m.name);const w=allyWeapon(m),hit=combatHitChance(allyAccuracy(m)+accMod+(combat.commandOrder==='focus'?8:0),enemyEvasion(t),24,93),heavy=mult>=1.4;if(rnd(1,100)>hit){combat.log.push(SOSText("combat_combat.allyStrike.001",m.name,t.name));sfxAttackForAlly(m,false,t,heavy);return false}let dmg=Math.max(2,Math.round(((w.damage||6)+boundedStatValue(allyStat(m,'str'))*.4+rnd(0,4)+allyClassBonus(m).damage+companionBonuses(m).damage)*mult));if(combat.commandOrder==='press')dmg=Math.round(dmg*1.15);if(m.role==='archer'||m.role==='scout')dmg+=2;if(m.role==='spear'&&['armored','stone','brute'].includes(t.trait))dmg+=4;if(m.role==='defector'&&t.trait==='commander')dmg+=4;if(t.trait==='armored'||t.trait==='stone'||t.trait==='shield')dmg=Math.round(dmg*(w.id==='named_hammer'?1.15:(t.guardBroken>0?.95:.86)));if(t.exposed>0||t.offBalance>0)dmg=Math.round(dmg*1.08);t.hp-=dmg;combat.log.push(SOSText("combat_combat.allyStrike.002",m.name,label,t.name,dmg));sfxAttackForAlly(m,true,t,heavy);return true}
function allyWizardAttack(m,t,blast=false){const d=Math.max(5,Math.round(7+allyStat(m,'int')*.9+(m.level||1)*1.5+(blast?6:0)+rnd(0,4)));t.hp-=d;combat.log.push(SOSText("combat_combat.allyWizardAttack.001",m.name,blast?'Magical Blast':'Magical Bolt',t.name,d));sfxCombatAttack('magic',true,['armored','stone','shield'].includes(t.trait),blast)}
function allyTurn(){let allies=partyMembers(true).filter(m=>m.hp>0).sort((a,b)=>allyInitiative(b)-allyInitiative(a));if(combat.opening&&!guardianOpeningClass()){const opp=allies.filter(m=>['Ranger','Rogue'].includes(m.className||allyDef(m.id)?.className));if(opp.length)allies=[...opp,...allies.filter(m=>!opp.includes(m))]}for(const m of allies){if(combat.enemies.every(e=>e.hp<=0))break;if(m.skipNext){m.skipNext=false;combat.log.push(SOSText("combat_combat.allyTurn.003",m.name));continue}if(m.role==='healer'&&allyHeal(m))continue;const cls=m.className||allyDef(m.id)?.className,openingTarget=combat.opening?combat.enemies.find(e=>e.id===combat.opening.target&&e.hp>0):null,preserve=openingTarget&&companionPreservesOpeningForGuardian(m);let t=preserve?allyTarget(m):(openingTarget||allyTarget(m));if(!t)t=allyTarget(m);if(!t)continue;m.classRank=classRank(m.level||state.level);if(openingTarget&&['Ranger','Rogue'].includes(cls)&&!preserve){const hit=allyStrike(m,openingTarget,cls==='Rogue'?1.7:1.35,cls==='Rogue'?16:20,cls==='Rogue'?'exploits the opening against':'fires through the opening at');combat.log.push(SOSText("combat_combat.allyTurn.010",m.name,openingTarget.name));if(hit)clearCombatOpening(openingTarget);continue}if(preserve&&t.id===openingTarget.id){const alternatives=combat.enemies.filter(e=>e.hp>0&&e.id!==openingTarget.id);if(alternatives.length)t=alternatives.slice().sort((a,b)=>companionTargetScore(m,b)-companionTargetScore(m,a))[0]}let hit=false,coord=companionCoordinationScore(m);if(['Wizard','Sorcerer'].includes(cls)){const blast=m.stamina>=18&&chance(.24+coord*.0018);allyWizardAttack(m,t,blast);if(blast)m.stamina-=18;hit=t.hp>0}else if(['Ranger','Rogue'].includes(cls)){if(m.stamina>=14&&chance(.27+coord*.0022)){m.stamina-=14;hit=allyStrike(m,t,.67,4,SOSText("combat_combat.allyTurn.015"));if(t.hp>0)hit=allyStrike(m,t,.67,2,SOSText("combat_combat.allyTurn.016"))||hit}else hit=allyStrike(m,t)}else if(['Vanguard','Warden','Berserker'].includes(cls)&&m.stamina>=14&&chance(.10+coord*.0018)){m.stamina-=14;if(chance(.42+coord*.0024)){hit=allyStrike(m,t,.78,3,SOSText("combat_combat.allyTurn.020"));if(hit&&t.hp>0&&!combat.opening)createCombatOpening(t,cls==='Warden'?'staggered':cls==='Vanguard'?'guardBroken':'offBalance',m.name,2)}else hit=allyStrike(m,t,1.42,-8,SOSText("combat_combat.allyTurn.022"))}else hit=allyStrike(m,t);if(t.hp>0)maybeCompanionCreateOpening(m,t,hit);if(preserve&&openingTarget&&combat.opening?.target===openingTarget.id&&coord>=65)combat.log.push(`${m.name} leaves the opening on ${openingTarget.name} for ${state.name} to exploit.`)}}
