 if(world){finalizeCombatWorldIncident(gr,combat.enemies,'guardian_retreat');const p=state.world.parties.find(x=>x.id===gr.worldPartyId);if(p){p.travelLeft=Math.max(0,(p.travelLeft||1)-1);addRoutePressure(p.location,p.destination,1)}recordWorldHistory(SOSText("combat_combat.completeRetreat.007",gr.name,terrain),'info','encounter');log(SOSText("combat_combat.completeRetreat.008",gr.name),'info');combat=null;save();closeOverlay();renderOpenWorld();return}
